typedef long long ll;
const int B=1e6;
const int mod1=998244353;
const int mod2=1e9+7;
ll n, counter;
vector<int> v[10];
int sum[10], answer, total;
inline int calc_mod(ll x){
	return (x%mod1+mod1)%mod1;	
}
void generate_sequences(int depth, int number){
	++counter;
	v[depth].push_back(calc_mod(counter - number));
	if(depth==6) return;
	for(int digit=0; digit<=9; ++digit){
		generate_sequences(depth+1, number*10+digit);
	}
}
void process_numbers(int depth, ll number){
	if(number>n) return;
	if(depth>=1){
		if(number*B>n/10 && (number+1)*B-1<=n){
			int multiplier=1;
			for(int i=0; i<=6; ++i, multiplier*=10){
				int w=calc_mod(counter - multiplier*number);
				int position=lower_bound(v[i].begin(), v[i].end(), mod1-w) - v[i].begin();
				answer=(answer + 1LL*w*v[i].size() + sum[i] - 1LL*mod1*((int)v[i].size() - position))%mod2;
			}
			counter+=total;
			return;
		}
